effect.shader:
// S_WarpWaves2 implementation for Alight Motion

#define PI 3.14159265359

vec2 applyWrap(vec2 uv, int mode) {
    if (mode == 1) return fract(uv); 
    if (mode == 2) return abs(mod(uv - 1.0, 2.0) - 1.0); 
    return uv;
}

vec2 getWaveOffset(vec2 p, float amp, float freq, float angle, float dispAngle, float pStart, float pSpeed, float time, float aspect) {
    float rad = angle * (PI / 180.0);
    float dispRad = dispAngle * (PI / 180.0);

    vec2 waveDir = vec2(cos(rad), sin(rad));
    vec2 dispDir = vec2(cos(rad + dispRad), sin(rad + dispRad));

    vec2 pCorrected = p;
    pCorrected.x *= aspect;

    float phase = dot(pCorrected, waveDir) * freq + pStart + time * pSpeed;

    return dispDir * sin(phase) * amp;
}

void main() {
    vec2 luv = acLayerNorm.xy;
    vec2 suv = acScreenNorm.xy;

    vec2 uv;
    vec2 aspect;
    if(followLayer) {
        uv = luv;
        aspect = vec2(acLayerSize.x / acLayerSize.y, 1.0);
    } else {
        uv = suv;
        aspect = vec2(acScreenSize.x / acScreenSize.y, 1.0);
    }

    // 2. Apply Z Dist (Zoom) from center
    vec2 p = (uv - 0.5) * zDist + 0.5;

    // 3. Calculate Displacement from Waves A and B
    vec2 offsetA = getWaveOffset(p, aAmplitude, aFrequency, aAngle, aDisplaceAngle, aPhaseStart, aPhaseSpeed, acTime, aspect.x);
    vec2 offsetB = getWaveOffset(p, bAmplitude, bFrequency, bAngle, bDisplaceAngle, bPhaseStart, bPhaseSpeed, acTime, aspect.x);

    // 4. Combine Warps
    // Offsets calculated in aspect-corrected space, divide X by aspect before adding to UV
    vec2 totalOffset = offsetA + offsetB;
    totalOffset.x /= aspect.x;

    vec2 warpedUV = p + totalOffset;

    // 5. Apply Wrap and Sample
    warpedUV = applyWrap(warpedUV, int(wrapMode));
    vec4 color = texture2DCv(inputImg.texture, warpedUV);

    vec4 base = texture2DCv(inputImg.texture, suv);
    gl_FragColor = mix(base, color, blend);
}
